import json, sys

def summarize_content(c, maxlen=300):
    if isinstance(c, str):
        return c[:maxlen].replace("\n", " ")
    if isinstance(c, list):
        parts = []
        for item in c:
            if not isinstance(item, dict):
                parts.append(str(item)[:100])
                continue
            t = item.get("type")
            if t == "text":
                parts.append("TEXT:" + item.get("text","")[:maxlen].replace("\n"," "))
            elif t == "tool_use":
                name = item.get("name")
                inp = json.dumps(item.get("input", {}))[:200]
                parts.append(f"TOOL_USE[{name}]:{inp}")
            elif t == "tool_result":
                content = item.get("content")
                if isinstance(content, list):
                    s = " ".join(str(x.get("text","")) if isinstance(x,dict) else str(x) for x in content)
                else:
                    s = str(content)
                err = item.get("is_error")
                parts.append(f"TOOL_RESULT(err={err}):{s[:maxlen].replace(chr(10),' ')}")
            else:
                parts.append(f"{t}:{json.dumps(item)[:150]}")
        return " | ".join(parts)
    return str(c)[:maxlen]

def main(path):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception as e:
                print("PARSE_ERROR", e)
                continue
            typ = d.get("type")
            ts = d.get("timestamp")
            if typ == "user" or typ == "assistant":
                msg = d.get("message", {})
                role = msg.get("role")
                content = msg.get("content")
                summary = summarize_content(content)
                print(f"[{ts}] {typ}/{role}: {summary}")
            elif "attachment" in d and d.get("attachment"):
                att = d["attachment"]
                hookname = att.get("hookName")
                content = att.get("content", "")
                if isinstance(content, str):
                    content = content[:200].replace("\n"," ")
                print(f"[{ts}] ATTACHMENT hook={hookname}: {content}")
            else:
                print(f"[{ts}] OTHER type={typ} keys={list(d.keys())}")

if __name__ == "__main__":
    main(sys.argv[1])

