import json, sys

def summarize_content(content, maxlen=300):
    if isinstance(content, str):
        s = content
    elif isinstance(content, list):
        parts = []
        for item in content:
            if isinstance(item, dict):
                t = item.get('type')
                if t == 'text':
                    parts.append(item.get('text',''))
                elif t == 'tool_use':
                    parts.append(f"[tool_use:{item.get('name')} input={json.dumps(item.get('input',{}))[:200]}]")
                elif t == 'tool_result':
                    c = item.get('content')
                    if isinstance(c, list):
                        c = ' '.join(x.get('text','') for x in c if isinstance(x,dict))
                    parts.append(f"[tool_result: {str(c)[:200]}]")
                elif t == 'image':
                    parts.append("[image]")
                else:
                    parts.append(f"[{t}]")
            else:
                parts.append(str(item))
        s = ' '.join(parts)
    else:
        s = str(content)
    s = s.replace('\n',' ')
    if len(s) > maxlen:
        s = s[:maxlen] + f"...<{len(s)} chars total>"
    return s

def main(path):
    with open(path) as fh:
        for i, line in enumerate(fh):
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except:
                print(f"[{i}] PARSE_ERROR")
                continue
            ts = obj.get('timestamp','')
            typ = obj.get('type', obj.get('attachment',{}).get('type') if obj.get('attachment') else None)
            role = None
            content_summary = ''
            msg = obj.get('message')
            if msg:
                role = msg.get('role')
                content_summary = summarize_content(msg.get('content',''))
            elif obj.get('attachment'):
                att = obj['attachment']
                role = 'attachment:' + str(att.get('type'))
                content_summary = summarize_content(att.get('content',''), maxlen=200)
            else:
                role = typ
            print(f"[{i}] ts={ts} role={role} :: {content_summary}")

if __name__ == '__main__':
    main(sys.argv[1])

